import java.math.BigDecimal;

public class TransactionStateOps {

    public BigDecimal usedToday(String id, String date, com.rustyledger.TransactionManager tm) {
        BigDecimal u = tm.used.get(id + "|" + date);
        return u == null ? new BigDecimal("0.00") : u;
    }

