            want = 4;
        } else if (verb.equals("DEPOSIT")) {
            want = 4;
        } else if (verb.equals("REVERSE")) {
            want = 3;
        } else {
            return tm.reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        }
        if (f.length != want) {
            return tm.reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        }
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            return tm.reject(verb, null, "BAD_DATE", date);
        }
        if (verb.equals("REVERSE")) {
            return tm.doReverse(date, f[2]);
        }
        String amountText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amountText.matches("\\d+(\\.\\d{1,2})?")) {
            return tm.reject(verb, date, "BAD_AMOUNT", amountText);
        }
        BigDecimal amount = new BigDecimal(amountText).setScale(2);
        if (amount.signum() <= 0) {
            return tm.reject(verb, date, "BAD_AMOUNT", amountText);
        }
        if (verb.equals("TRANSFER")) {
            return tm.doTransfer(date, f[2], f[3], amount, f[5]);
        } else if (verb.equals("WITHDRAW")) {
            return tm.doWithdraw(date, f[2], amount);
        }
        return tm.doDeposit(date, f[2], amount);
