package com.rustyledger;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class TxFee {

    public static BigDecimal calculateTransferFee(BigDecimal amount, String tier) {
        if (tier.equals("STANDARD")) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        } else if (tier.equals("PREMIUM")) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        } else {
            return new BigDecimal("0.00");
        }
    }

    public static BigDecimal rate(String currency) {
        if (currency.equals("EUR")) {
            return new BigDecimal("4.30");
        } else if (currency.equals("USD")) {
            return new BigDecimal("4.00");
        }
        return new BigDecimal("1.00");
    }

    public static BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!tier.equals("STAFF")) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }

    public static boolean checkLimit(String date, String id, String tier,
            java.util.Map<String, BigDecimal> used, java.util.Map<String, BigDecimal> limits) {
        BigDecimal limit = limits.get(tier);
        if (limit == null) {
            if (tier.equals("STANDARD")) limit = new BigDecimal("5000.00");
            else if (tier.equals("PREMIUM")) limit = new BigDecimal("20000.00");
            else limit = new BigDecimal("50000.00");
            limits.put(tier, limit);
        }
        BigDecimal usedToday = used.get(id + "|" + date);
        if (usedToday == null) {
            if (tier.equals("STANDARD")) usedToday = new BigDecimal("0.00");
            else if (tier.equals("PREMIUM")) usedToday = new BigDecimal("0.00");
            else usedToday = new BigDecimal("0.00");
        }
        if (usedToday.add(amount).compareTo(limit) > 0) {
            return true; // limit exceeded
        }
        return false;
    }

    public static String insufficientFundsMsg(String id, String currency, BigDecimal balance,
            BigDecimal needed) {
        return "INSUFFICIENT_FUNDS: balance " + balance + " " + currency + ", needed " + needed + " " + currency;
    }
}

