    private String checkLimitAndFunds(String date, String id, Object[] a, BigDecimal amt, BigDecimal fee) {
        String tier = (String) a[0];
        BigDecimal limit;
        BigDecimal overdraft = new BigDecimal("0.00");
        if (tier.equals("STANDARD")) limit = new BigDecimal("5000.00");
        else if (tier.equals("PREMIUM")) { limit = new BigDecimal("20000.00"); overdraft = new BigDecimal("500.00"); }
        else limit = new BigDecimal("50000.00");
        if (usedToday(id, date).add(amt).compareTo(limit) > 0) return "LIMIT_EXCEEDED: daily limit " + limit + " for " + tier;
        BigDecimal bal = (BigDecimal) a[2];
        BigDecimal needed = amt.add(fee);
        if (bal.subtract(needed).compareTo(overdraft.negate()) < 0) return "INSUFFICIENT_FUNDS: balance " + bal + " " + a[1] + ", needed " + needed + " " + a[1];
        return null;
    }

    private BigDecimal usedToday(String id, String date) {
        BigDecimal u = used.get(id + "|" + date);
        return u == null ? new BigDecimal("0.00") : u;
    }

    private BigDecimal rate(String currency) {
        if (currency.equals("EUR")) return new BigDecimal("4.30");
        if (currency.equals("USD")) return new BigDecimal("4.00");
        return new BigDecimal("1.00");
    }

    private BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
