    static class ReverseHandler {
        private final TransactionManager tm;

        ReverseHandler(TransactionManager tm) { this.tm = tm; }

        String doReverse(String date, String txId) {
            String[] tx = tm.txs.get(txId);
            if (tx == null) return tm.reject("REVERSE", date, "UNKNOWN_TX", txId);
            if (!tx[0].equals("TRANSFER")) return tm.reject("REVERSE", date, "NOT_REVERSIBLE", txId + " is a " + tx[0]);
            if (tx[8].equals("Y")) return tm.reject("REVERSE", date, "ALREADY_REVERSED", txId);
            if (!tx[1].equals(date)) return tm.reject("REVERSE", date, "REVERSAL_WINDOW", txId + " was made on " + tx[1]);

            Object[] from = tm.accounts.get(tx[2]);
            Object[] to = tm.accounts.get(tx[3]);
            BigDecimal fee = new BigDecimal(tx[6]);
            BigDecimal back = new BigDecimal(tx[4]);
            if (from[0].equals("PREMIUM")) {
                back = back.add(fee);
                if (fee.signum() != 0) tm.addFee(date, (String) from[1], fee.negate());
            }
            from[2] = ((BigDecimal) from[2]).add(back);
            tx[8] = "Y";

            tm.txSeq++;
            String newId = String.format("TX-%06d", tm.txSeq);
            tm.txs.put(newId, new String[]{"REVERSE", date, tx[2], tx[3], tx[4], tx[5], "0.00", tx[7], "Y"});

