package com.rustyledger;

import com.rustyledger.Ledger;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class TransactionManager implements Ledger {
    final Map<String, Object[]> accounts = new HashMap<>();
    final Map<String, BigDecimal> used = new HashMap<>();
    final Map<String, String[]> txs = new LinkedHashMap<>();
    final List<String> audit = new ArrayList<>();
    final Map<String, int[]> counts = new HashMap<>();
    final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();
    int auditSeq = 0, txSeq = 0;

    // Collaborator objects
    final TxAccounts txAccounts = new TxAccounts();
    final TxFeeCalc txFeeCalc = new TxFeeCalc();
    final TxLimits txLimits = new TxLimits();
    final TxReport txReport = new TxReport();
    final TxReverse txReverse = new TxReverse();
    final TxInstruction txInstr = new TxInstruction();

    public void openAccount(String id, String tier, String currency, String openingBalance) {
        txAccounts.openAccount(id, tier, currency, openingBalance, accounts);
    }

    public String balance(String id) {
        return txAccounts.balance(id, accounts);
    }

    public String submit(String line) {
        if (line == null || line.trim().isEmpty()) {
            return "REJECTED BAD_INSTRUCTION: empty instruction";
        }
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want;
        if (verb.equals("TRANSFER")) want = 6;
        else if (verb.equals("WITHDRAW")) want = 4;
        else if (verb.equals("DEPOSIT")) want = 4;
        else if (verb.equals("REVERSE")) want = 3;
        else return "REJECTED BAD_INSTRUCTION: unknown verb " + verb;
        if (f.length != want) return "REJECTED BAD_INSTRUCTION: " + verb + " needs " + want + " fields";
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return "REJECTED BAD_DATE: " + date;
        if (verb.equals("REVERSE")) return txReverse.doReverse(date, f[2], txs, accounts, audit, auditSeq, counts, fees, used, txSeq);

        String amountText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amountText.matches("\\d+(\\.\\d{1,2})?")) return "REJECTED BAD_AMOUNT: " + amountText;
        BigDecimal amount = new BigDecimal(amountText).setScale(2);
        if (amount.signum() <= 0) return "REJECTED BAD_AMOUNT: " + amountText;

        // Dispatch based on verb
        if (verb.equals("TRANSFER")) return doTransfer(date, f[2], f[3], amount, f[5]);
        else if (verb.equals("WITHDRAW")) return doWithdraw(date, f[2], amount);
        return doDeposit(date, f[2], amount);
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amount, String currency) {
        Object[] from = accounts.get(fromId);
        if (from == null) return "REJECTED UNKNOWN_ACCOUNT: " + fromId;
        Object[] to = accounts.get(toId);
        if (to == null) return "REJECTED UNKNOWN_ACCOUNT: " + toId;
        if (fromId.equals(toId)) return "REJECTED SAME_ACCOUNT: cannot transfer to the same account";
        String fromCur = (String) from[1];
        if (!fromCur.equals(currency)) return "REJECTED CURRENCY_MISMATCH: " + fromId + " holds " + fromCur;
        String tier = (String) from[0];
        BigDecimal fee = txFeeCalc.calculateTransferFee(amount, tier);

        // Check limits and funds
        String rejection = txLimits.checkLimitAndFunds(date, fromId, from, amount, fee);
        if (rejection != null) return "REJECTED " + rejection;

        BigDecimal credited = amount;
        String toCur = (String) to[1];
        if (!fromCur.equals(toCur)) credited = txFeeCalc.convert(amount, fromCur, toCur, tier);

        // Apply state changes
        from[2] = ((BigDecimal) from[2]).subtract(amount.add(fee));
        to[2] = ((BigDecimal) to[2]).add(credited);
        used.put(fromId + "|" + date, txLimits.usedToday(fromId, date).add(amount));

        // Record transaction
        txSeq++;
        String txId = String.format("TX-%06d", txSeq);
        txs.put(txId, new String[]{"TRANSFER", date, fromId, toId, amount.toString(), fromCur, fee.toString(), credited.toString(), "N"});
        txFeeCalc.addFee(date, fromCur, fee, fees);

        return "OK TX-" + String.format("%06d", txId) + " fee=" + fee + " " + fromCur;
    }

    private String doWithdraw(String date, String id, BigDecimal amount) {
        Object[] a = accounts.get(id);
        if (a == null) return "REJECTED UNKNOWN_ACCOUNT: " + id;
        String tier = (String) a[0];
        BigDecimal fee = tier.equals("STANDARD") ? new BigDecimal("1.00") : new BigDecimal("0.00");

        String rejection = txLimits.checkLimitAndFunds(date, id, a, amount, fee);
        if (rejection != null) return "REJECTED " + rejection;

        a[2] = ((BigDecimal) a[2]).subtract(amount.add(fee));
        used.put(id + "|" + date, txLimits.usedToday(id, date).add(amount));

        txSeq++;
        String txId = String.format("TX-%06d", txSeq);
        txs.put(txId, new String[]{"WITHDRAW", date, id, "", amount.toString(), (String) a[1], fee.toString(), amount.toString(), "N"});
        txFeeCalc.addFee(date, (String) a[1], fee, fees);

        return "OK TX-" + String.format("%06d", txId) + " fee=" + fee + " " + a[1];
    }

    private String doDeposit(String date, String id, BigDecimal amount) {
        Object[] a = accounts.get(id);
        if (a == null) return "REJECTED UNKNOWN_ACCOUNT: " + id;
        a[2] = ((BigDecimal) a[2]).add(amount);

        txSeq++;
        String txId = String.format("TX-%06d", txSeq);
        txs.put(txId, new String[]{"DEPOSIT", date, id, "", amount.toString(), (String) a[1], "0.00", amount.toString(), "N"});

        return "OK TX-" + String.format("%06d", txId) + " fee=0.00 " + a[1];
    }

    // Helper: used today (extracted from TxLimits pattern)
    private BigDecimal usedToday(String id, String date) {
        BigDecimal u = used.get(id + "|" + date);
        return u == null ? new BigDecimal("0.00") : u;
    }

    // The reject/accept methods (Lamp methods - keep unchanged for audit/count tracking)
    String reject(String verb, String date, String code, String message) {
        if (date != null) { int[] c2 = counts.get(date); if (c2 == null) { c2 = new int[2]; counts.put(date, c2); } c2[1]++; }
        String displayDate = date != null ? date : "????-????";
        auditSeq++; audit.add(String.format("%03d  %s %s %s", auditSeq, verb, displayDate, "REJECTED " + code));
        return "REJECTED " + code + ": " + message;
    }

    String accept(String verb, String date, String txId, String extra) {
        int[] c2 = counts.get(date);
