            java.util.List<String> audit,
            int auditSeq,
            java.util.Map<String, int[]> counts,
            java.util.Map<String, BigDecimal> used,
            int txSeq) {

        if (line == null || line.trim().isEmpty()) {
            if (auditSeq != -1) { auditSeq++; }
            audit.add(String.format("%03d  ???? ????-???? REJECTED BAD_INSTRUCTION", auditSeq, "empty instruction"));
            return "REJECTED BAD_INSTRUCTION: empty instruction";
        }

        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want;
        if (verb.equals("TRANSFER")) want = 6;
        else if (verb.equals("WITHDRAW")) want = 4;
        else if (verb.equals("DEPOSIT")) want = 4;
        else if (verb.equals("REVERSE")) want = 3;
        else return "REJECTED BAD_INSTRUCTION: unknown verb " + verb;

        if (f.length != want) {
            return "REJECTED BAD_INSTRUCTION: " + verb + " needs " + want + " fields";
        }

        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) {
            return "REJECTED BAD_DATE: " + date;
        }

        if (verb.equals("REVERSE")) {
            return TxReverse.doReverse(date, f[2], txs, audit, auditSeq, counts, fees, used, txSeq);
        }

        String amountText = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amountText.matches("\\d+(\\.\\d{2})?")) {
            return "REJECTED BAD_AMOUNT: " + amountText;
        }
        BigDecimal amount = new BigDecimal(amountText).setScale(2);
        if (amount.signum() <= 0) {
            return "REJECTED BAD_AMOUNT: " + amountText;
        }

        if (verb.equals("TRANSFER")) {
            return "TRANSFER_DISPATCH:" + date + ":" + f[2] + ":" + f[3] + ":" + amount + ":" + f[5];
        } else if (verb.equals("WITHDRAW")) {
            return "WITHDRAW_DISPATCH:" + date + ":" + f[2] + ":" + amount;
        } else if (verb.equals("DEPOSIT")) {
            return "DEPOSIT_DISPATCH:" + date + ":" + f[2] + ":" + amount;
        }

        return "OK";
    }
